   attack {:default 0.001 :min 0.001 :max 1.0 :step 0.001}
   decay  {:default 0.4 :min 0.001 :max 1 :step 0.001}]
  (let [env (env-gen (perc attack decay) :action FREE)
        snd (sin-osc freq (* Math/PI 0.5))
        snd (* amp env snd)]
    snd))

